package org.urbanchaos.diagnostic;
import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import android.database.Cursor;
import org.json.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.function.Consumer;
/** Private staging and atomic pointer activation. A failed import cannot replace the current game. */
final class Importer {
 final Context context;final Consumer<String> progress;final File root,stage,journal;volatile boolean cancelled;
 static final String HASH="b74ae76fdbf1ef5f95dcfabf4f94f3aa738e649ecaef4068d8531e07071b5dac";
 Importer(Context c,Consumer<String> p){context=c.getApplicationContext();progress=p;root=context.getFilesDir();stage=new File(root,"import-staging");journal=new File(root,"import-session.json");}
 void cancel(){cancelled=true;}
 void check() throws IOException{if(cancelled)throw new IOException("Importação pausada; use Retomar");}
 static void atomic(File f,String s)throws IOException{File tmp=new File(f.getPath()+".tmp");try(FileOutputStream o=new FileOutputStream(tmp)){o.write(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));o.getFD().sync();}Files.move(tmp.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 static String name(String s)throws IOException{return StoragePaths.name(s);}

 File target(String rel)throws IOException{File f=new File(stage,rel);if(!f.getCanonicalPath().startsWith(stage.getCanonicalPath()+File.separator))throw new IOException("Caminho externo recusado");return f;}
 void discard(){cancel();try{if(stage.exists())try(java.util.stream.Stream<Path> paths=Files.walk(stage.toPath())){for(Path p:(Iterable<Path>)paths.sorted(java.util.Comparator.reverseOrder())::iterator)Files.delete(p);}journal.delete();progress.accept("Staging descartado; instalação e saves preservados");}catch(Exception e){progress.accept(e.getMessage());}}
 void start(Uri uri,boolean tree){try{if(journal.exists())throw new IOException("Já existe sessão interrompida. Retome antes de importar outra origem.");stage.mkdirs();JSONObject j=new JSONObject();j.put("uri",uri.toString());j.put("tree",tree);atomic(journal,j.toString());resume();}catch(Exception e){progress.accept(e.getMessage());}}
 void resume(){cancelled=false;try{if(!journal.exists())throw new IOException("Nenhuma importação pendente");JSONObject j=new JSONObject(new String(Files.readAllBytes(journal.toPath()),java.nio.charset.StandardCharsets.UTF_8));Uri u=Uri.parse(j.getString("uri"));boolean tree=j.getBoolean("tree");
 if(j.has("pending")){String pending=j.getString("pending");if(!pending.matches("installation-[a-f0-9-]+"))throw new IOException("Sessão inválida");File installed=new File(root,"game/"+pending);if(installed.isDirectory()){File executable=null;for(File f:installed.listFiles())if(f.getName().equalsIgnoreCase("Default.xbe"))executable=f;if(executable==null)throw new IOException("Instalação incompleta");validate(executable);atomic(new File(root,"game/active.json"),new JSONObject().put("directory",pending).put("sha256",HASH).put("qualification","NOT_GAME_QUALIFIED").toString());journal.delete();progress.accept("Ativação retomada; G1 continua bloqueado");return;}}

 if(tree){String id=DocumentsContract.getTreeDocumentId(u);walk(u,id,"",0,new HashSet<>(),new HashSet<>());}
 else {File image=target("source.image");long n=size(u);copy(u,image,n);try(RandomAccessFile f=new RandomAccessFile(image,"r")){if(f.length()<4)throw new IOException("Arquivo truncado");byte[] magic=new byte[4];f.readFully(magic);if(Arrays.equals(magic,new byte[]{'X','B','E','H'})){Files.copy(image.toPath(),target("Default.xbe").toPath(),StandardCopyOption.REPLACE_EXISTING);}else new Xiso(image,stage,this::check).extract();}}
 File xbe=null;for(File f:stage.listFiles())if(f.getName().equalsIgnoreCase("default.xbe")){if(xbe!=null)throw new IOException("Default.xbe duplicado");xbe=f;}if(xbe==null)throw new IOException("Default.xbe ausente na raiz");
 validate(xbe);check();new File(stage,"source.image").delete();
 String id="installation-"+UUID.randomUUID();File installed=new File(new File(root,"game"),id);j.put("pending",id);atomic(journal,j.toString());if(!stage.renameTo(installed))throw new IOException("Não foi possível ativar staging");atomic(new File(root,"game/active.json"),new JSONObject().put("directory",id).put("sha256",HASH).put("qualification","NOT_GAME_QUALIFIED").toString());journal.delete();progress.accept("Importação validada e ativada. G1 continua bloqueado; nenhum jogo executado.");
 }catch(Exception e){progress.accept("Importação não ativada: "+e.getMessage());}}
 long size(Uri u)throws IOException{try(Cursor c=context.getContentResolver().query(u,new String[]{DocumentsContract.Document.COLUMN_SIZE},null,null,null)){if(c!=null&&c.moveToFirst()&&!c.isNull(0))return c.getLong(0);}throw new IOException("Provedor SAF não informa tamanho; não é possível validar retomada");}
 void copy(Uri u,File dst,long n)throws Exception{check();if(n<0)throw new IOException("Tamanho inválido");dst.getParentFile().mkdirs();File part=new File(dst.getPath()+".part");long done=part.exists()?part.length():0;if(dst.exists()){Files.move(dst.toPath(),part.toPath(),StandardCopyOption.REPLACE_EXISTING);done=part.length();}if(done>n){part.delete();done=0;}
 if(root.getUsableSpace()<n-done+64L*1024*1024)throw new IOException("Espaço insuficiente");
 try(InputStream src=context.getContentResolver().openInputStream(u);RandomAccessFile out=new RandomAccessFile(part,"rw")){if(src==null)throw new IOException("Origem indisponível");byte[] b=new byte[1024*1024];long verified=0;while(verified<done){check();int k=src.read(b,0,(int)Math.min(b.length,done-verified));if(k<0)throw new IOException("Origem truncada ao retomar");byte[] old=new byte[k];out.readFully(old);for(int i=0;i<k;i++)if(old[i]!=b[i])throw new IOException("Origem alterada; prefixo de retomada não confere");verified+=k;}
 while(done<n){check();int k=src.read(b,0,(int)Math.min(b.length,n-done));if(k<0)throw new IOException("Arquivo truncado");out.write(b,0,k);done+=k;progress.accept("Copiando "+dst.getName()+": "+done+" / "+n);}
 if(src.read()!=-1)throw new IOException("Tamanho da origem alterado");out.getFD().sync();}Files.move(part.toPath(),dst.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 void walk(Uri tree,String id,String prefix,int depth,Set<String> seen,Set<String> names)throws Exception{check();if(depth>64||!seen.add(id))throw new IOException("Ciclo de diretórios");Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=context.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE},null,null,null)){if(c==null)throw new IOException("Diretório inacessível");while(c.moveToNext()){check();String child=c.getString(0),rel=prefix+name(c.getString(1));if(rel.endsWith(".part")||rel.equals("source.image"))throw new IOException("Nome reservado para staging");if(!names.add(rel.toLowerCase(Locale.ROOT))||names.size()>250000)throw new IOException("Colisão/limite de caminhos");if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2)))walk(tree,child,rel+"/",depth+1,seen,names);else{if(c.isNull(3))throw new IOException("Tamanho ausente");copy(DocumentsContract.buildDocumentUriUsingTree(tree,child),target(rel),c.getLong(3));}}}}
 static void validate(File xbe)throws Exception{if(xbe.length()!=5283840)throw new IOException("Tamanho XBE incompatível com candidato Xbox");MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(xbe)){byte[] b=new byte[1048576];int n;while((n=in.read(b))!=-1)md.update(b,0,n);}StringBuilder h=new StringBuilder();for(byte b:md.digest())h.append(String.format("%02x",b&255));if(!HASH.equals(h.toString()))throw new IOException("SHA-256 incompatível com candidato Xbox; não ativado");}
}
